import { Component, h, State, Prop } from '@stencil/core';

export interface slideInterface {
  text?: string;
  imageUrl?: string;
}

@Component({
  tag: 'std-slider',
  styleUrl: 'std-slider.css',
  shadow: true
})
export class StdSliderComponent {
  @State() currentIndex: number = 0;
  @State() startX: number = 0;
  @State() currentX: number = 0;

  @Prop() slides: Array<slideInterface> = [];

  private isDragging: boolean = false;

  handleMouseDown(event: MouseEvent) {
    event.stopPropagation();
    this.isDragging = true;
    this.startX = event.pageX;
    this.currentX = event.pageX;
    window.addEventListener('mousemove', this.handleMouseMove);
    window.addEventListener('mouseup', this.handleMouseUp);
  }

  handleMouseMove = (event: MouseEvent) => {
    this.currentX = event.pageX;
    if (!this.isDragging) return;
  };

  // T0D0: Seguir agregando el estilo de movimiento
  handleMouseUp = () => {
    const movementX = this.currentX - this.startX;
    if (movementX < -50) {
      this.showNextSlide();
    } else if (movementX > 50) {
      this.showPreviousSlide();
    }
    if (!this.isDragging) return;
    this.isDragging = false;

    window.removeEventListener('mousemove', this.handleMouseMove);
    window.removeEventListener('mouseup', this.handleMouseUp);
  };

  showNextSlide() {
    this.currentIndex = (this.currentIndex + 1) % this.slides.length;
  }

  showPreviousSlide() {
    this.currentIndex = (this.currentIndex - 1 + this.slides.length) % this.slides.length;
  }

  handleDragStart(event: DragEvent) {
    event.preventDefault();
  }

  render() {
    const showPagination = this.slides && this.slides.length > 1;

    return (
      <div class="slider-container" onMouseDown={event => this.handleMouseDown(event)} onDragStart={event => this.handleDragStart(event)}>
        <div
          class="slider"
          style={{
            transform: `translateX(-${this.currentIndex * 100}%)`,
            transition: this.isDragging ? 'none' : 'transform 0.3s ease'
          }}>
          {this.slides.map(slide => (
            <div class="slide bg-alternative-light">
              <div class="bg-alternative-light !h-[134px] flex items-center justify-center rounded-[10px]">
                <div class="before:content-[''] before:absolute before:top-0 before:left-0 before:bg-gradient-to-r before:from-dark/50 before:to-dark/0 before:w-3/4 before:h-full before:rounded-xl w-full rounded-xl relative h-[134px]">
                  {slide.text && (
                    <div class="flex items-center justify-between w-full h-full absolute bottom-0 left-0 lg:left-8 top-0 lg:max-w-[421px] px-8 lg:px-0">
                      <h2 class="text-lg text-white font-sans flex items-center gap-2 relative pl-3 before:content-[''] before:absolute before:top-2 before:left-0 before:w-1 before:h-[14px] before:bg-primary">
                        {slide.text}
                      </h2>
                    </div>
                  )}
                  {slide.imageUrl && (
                    <std-image
                      classes="block w-full h-full"
                      imageClasses="aspect-[3/1] lg:aspect-auto rounded-xl object-cover object-top"
                      src={slide.imageUrl}
                      srcDesktop={slide.imageUrl}
                      alt="banner"
                    />
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
        {showPagination && (
          <div class="pagination">
            {this.slides.map((_, index) => (
              <button class={{ active: this.currentIndex === index }} onClick={() => (this.currentIndex = index)}></button>
            ))}
          </div>
        )}
      </div>
    );
  }
}
